TASK:{"title":"SWEN3204 Software Architecture – Assignment 2: Short-Answer Questions","overview":"Answer six short questions applying architecture concepts to the CampusEats scenario. The assignment is worth 40 marks, including 4 marks for communication. Submit an individual, single-document response."}
RUBRIC:[{"id":"C1","name":"Q1 Quality attributes","weight":null,"max":6,"levels":[{"label":"Excellent","min":5,"max":6,"desc":"Two attributes that clearly matter most are chosen and justified from the scenario. Both scenarios have all six parts and both response measures are measurable."},{"label":"Proficient","min":3,"max":4,"desc":"Suitable attributes are chosen with some justification. Scenarios are mostly complete but one is missing a part or has a response measure that is not measurable."},{"label":"Developing","min":1,"max":2,"desc":"Attributes are named with little or no justification, or the scenarios are not in six-part form or are not measurable."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted or irrelevant."}]},{"id":"C2","name":"Q2 Architectural style","weight":null,"max":6,"levels":[{"label":"Excellent","min":5,"max":6,"desc":"A clear recommendation justified by at least two trade-offs that are specific to the scenario (team size, load profile, known problems). The downside of the recommendation is acknowledged."},{"label":"Proficient","min":3,"max":4,"desc":"A clear recommendation with two trade-offs, but one is generic or not linked to the scenario, or no downside is acknowledged."},{"label":"Developing","min":1,"max":2,"desc":"A recommendation with only one trade-off, or with generic textbook advantages and disadvantages only."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted or no recommendation."}]},{"id":"C3","name":"Q3 Availability calculation","weight":null,"max":8,"levels":[{"label":"Excellent","min":7,"max":8,"desc":"Parts (a), (b) and (c) are all correct with working shown, to the requested precision."},{"label":"Proficient","min":5,"max":6,"desc":"The method is correct throughout but there is one arithmetic or rounding slip, or exactly one part is incorrect."},{"label":"Developing","min":1,"max":4,"desc":"The series calculation is attempted but two or more parts are incorrect, or working is not shown."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted or no correct element."}]},{"id":"C4","name":"Q4 Resilience pattern","weight":null,"max":5,"levels":[{"label":"Excellent","min":5,"max":5,"desc":"An appropriate pattern is named, its mechanism is explained correctly, it is applied to the outage, and at least one drawback or tuning consideration is given."},{"label":"Proficient","min":3,"max":4,"desc":"An appropriate pattern is named and explained correctly, but it is only loosely applied to the outage or no drawback or tuning consideration is given."},{"label":"Developing","min":1,"max":2,"desc":"A pattern is named but the explanation is incorrect or very thin."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted or an unsuitable pattern."}]},{"id":"C5","name":"Q5 Consistency and availability","weight":null,"max":6,"levels":[{"label":"Excellent","min":5,"max":6,"desc":"Both choices are justified, the CAP theorem is used correctly, and a suitable concrete technique is named for each case."},{"label":"Proficient","min":3,"max":4,"desc":"Both choices are reasonable and techniques are named, but the CAP theorem is explained incorrectly or imprecisely, or one technique is missing."},{"label":"Developing","min":1,"max":2,"desc":"Choices are stated with little justification, or the CAP theorem is not used."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted."}]},{"id":"C6","name":"Q6 Architecture decision record","weight":null,"max":5,"levels":[{"label":"Excellent","min":5,"max":5,"desc":"Context, Decision and Consequences are all present and specific to the scenario, with at least one positive and one negative consequence."},{"label":"Proficient","min":3,"max":4,"desc":"All three sections are present but the consequences are one-sided (no negative consequence) or the context is generic."},{"label":"Developing","min":1,"max":2,"desc":"One or more sections are missing or the record does not describe a decision."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted."}]},{"id":"C7","name":"Communication and format","weight":null,"max":4,"levels":[{"label":"Excellent","min":4,"max":4,"desc":"Every answer is within 150 words, terminology is precise, the required headings are used and sources are cited in IEEE style."},{"label":"Proficient","min":3,"max":3,"desc":"Clear writing, but one answer exceeds the word limit or there are minor citation or formatting problems."},{"label":"Developing","min":1,"max":2,"desc":"Several answers exceed the word limit, or the writing is hard to follow, or sources are not cited."},{"label":"Missing","min":0,"max":0,"desc":"Format requirements ignored."}]}]
MARKING:{"requirements":[{"id":"R1","met":"partial","where":"Question 1"},{"id":"R2","met":"yes","where":"Question 2"},{"id":"R3","met":"partial","where":"Question 3"},{"id":"R4","met":"yes","where":"Question 4"},{"id":"R5","met":"partial","where":"Question 5"},{"id":"R6","met":"partial","where":"Question 6"},{"id":"R7","met":"partial","where":null}],"technical_issues":[{"where":"Question 3","issue":"Part (c) reports payment-only availability (99.9975%) as end-to-end availability. End-to-end is about 99.80% (0.99797630), with about 1.5 h monthly downtime, not 0.018 h."},{"where":"Question 3","issue":"Results 99.9975% and 0.018 hours break the required precision of two decimals for percentages and one decimal for hours."},{"where":"Question 5","issue":"States that payments give up partition tolerance. Partitions cannot be avoided in a distributed system, so the choice is consistency or availability during a partition."},{"where":"Question 1","issue":"Availability response measure ('stay up most of the time') is not measurable."},{"where":"Question 6","issue":"Consequences omit negative effects such as duplicate deliveries, message ordering and extra operational load of RabbitMQ."},{"where":"Question 4","issue":"Claims the breaker would have opened within seconds during the outage without supporting data."}],"overall":"Solid structure and a sound modular monolith recommendation, but Question 3(c) is wrong and Question 5 misstates CAP. Q1 availability measure is not measurable, the ADR lacks a negative consequence, several answers exceed 150 words, and assumptions are not stated. Total 27/40.","criteria":[{"id":"C1","level":"Proficient","mark":4.0,"scale":6.0,"points":4.0,"max":6.0,"reasoning":"Performance and availability are chosen and justified from the scenario. The performance scenario has all six parts with a measurable p95 target. The availability scenario's response measure ('stay up most of the time') is not measurable, so this level applies.","evidence":[{"where":"Question 1","quote":"Response measure: the system should stay up most of the time."},{"where":"Question 1","quote":"the business depends on the lunch hour: 900 orders arrive between 12:00 and 13:00"}]},{"id":"C2","level":"Excellent","mark":5.0,"scale":6.0,"points":5.0,"max":6.0,"reasoning":"The modular monolith recommendation is clear. Two scenario-specific trade-offs are given: team size versus operational overhead, and the single-VM and deployment-downtime problems. The downside (no independent scaling, shared process failure) is acknowledged.","evidence":[{"where":"Question 2","quote":"With five developers, running eight or ten services would mean more time spent on infrastructure than on features."},{"where":"Question 2","quote":"The trade-off I accept is that modules cannot be scaled independently"}]},{"id":"C3","level":"Proficient","mark":5.0,"scale":8.0,"points":5.0,"max":8.0,"reasoning":"Parts (a) 99.30% and (b) 5.0 h are correct with working. Part (c) is wrong: it reports payment-only availability as end-to-end. The correct end-to-end value is about 99.80% and about 1.5 h/month. Results also break the two-decimal and one-decimal precision rules.","evidence":[{"where":"Question 3","quote":"So the new availability of placing an order is 99.9975%"},{"where":"Question 3","quote":"which reduces the downtime to 0.000025 × 720 = 0.018 hours"}]},{"id":"C4","level":"Proficient","mark":4.0,"scale":5.0,"points":4.0,"max":5.0,"reasoning":"Circuit Breaker is an appropriate pattern and its states are explained correctly. It is applied to the outage. No drawback is given. The threshold mention is an example, not a tuning trade-off. The claim that it would have opened within seconds is unsupported.","evidence":[{"where":"Question 4","quote":"the breaker would have opened within seconds of the provider slowing down"},{"where":"Question 4","quote":"When failures exceed a threshold (for example 50% of calls in 10 seconds)"}]},{"id":"C5","level":"Proficient","mark":4.0,"scale":6.0,"points":4.0,"max":6.0,"reasoning":"Both choices are reasonable and each has a concrete technique (Redis TTL cache, idempotency keys). The CAP explanation is wrong: partition tolerance cannot be given up in a distributed system, and the choice is between consistency and availability during a partition.","evidence":[{"where":"Question 5","quote":"so for payments we choose consistency and availability and give up partition tolerance"},{"where":"Question 5","quote":"for example Redis with a 60-second TTL"}]},{"id":"C6","level":"Proficient","mark":3.0,"scale":5.0,"points":3.0,"max":5.0,"reasoning":"Context, Decision and Consequences are present and specific to the scenario. The consequences list only positive effects, with no negative consequence such as duplicate delivery, ordering issues or added queue operations.","evidence":[{"where":"Question 6","quote":"Context: After an order is paid, the application calls the outlet's tablet synchronously and waits for the reply."},{"where":"Question 6","quote":"Consequences: Placing an order no longer waits for the outlet, so the response time improves."}]},{"id":"C7","level":"Developing","mark":2.0,"scale":4.0,"points":2.0,"max":4.0,"reasoning":"Several answers exceed 150 words, including Questions 2, 4 and 5. Headings are correct and IEEE references [1] and [2] are cited with a reference list. No assumptions section is given, although the task requires one.","evidence":[{"where":"Question 2","quote":"I recommend against a full microservices rewrite for the next 12 months."},{"where":"Question 4","quote":"The Circuit Breaker pattern [2] would have contained the failure."}]}]}
